UI=r'''
<div class="tabsec" id="tab_proofread"><div class="card">
<h2>ตรวจคำ · ซับและ Super Text</h2><p class="hint">ตรวจภาษาไทยและอังกฤษบนไทม์ไลน์ล่าสุดด้วย UTCC · คำเสนอแก้ยังไม่เปลี่ยนไฟล์จนกว่าคุณจะเลือกบันทึก</p>
<div class="row"><label for="prMode">วิธีตรวจ</label><select id="prMode" onchange="prModeChanged()"><option value="spelling">เฉพาะคำสะกดผิด (แนะนำ)</option><option value="full">ตรวจทั้งหมด รวมคำไม่แน่ใจและเว้นวรรค</option></select></div><p class="hint">เฉพาะคำสะกดผิด: คงสำนวน คำทับศัพท์ และเว้นวรรคเดิม ไม่เสนอแก้ชื่อหรือคำที่ไม่แน่ใจ</p>
<div class="btns"><button id="prLoad" onclick="prLoad()">โหลดข้อความล่าสุด</button><button id="prScan" class="primary" onclick="prScan()">ตรวจคำด้วย UTCC</button><button id="prSave" onclick="prSave()" disabled>บันทึกเฉพาะที่เลือก + สำรอง</button><button onclick="studioOpenHistory()">ประวัติ / กู้คืน</button><button id="prCancel" onclick="prCancel()" disabled>ยกเลิกตรวจ</button></div>
<p id="prStatus" role="status" aria-live="polite"></p><div class="row"><label>ดูผล <select id="prFilter" onchange="prRender()"><option value="all">ทั้งหมด</option><option value="spelling">คำเสนอแก้</option><option value="uncertain">คำไม่แน่ใจ</option><option value="format">เว้นวรรค / รูปแบบ</option></select></label></div>
<div id="prResults"></div><details><summary>ศัพท์เฉพาะที่ยืนยันแล้ว</summary><p class="hint">บันทึกเฉพาะคำหรือชื่อที่ตรวจแล้ว ไม่ใช้ทั้งประโยค</p><input id="prWord" maxlength="80" placeholder="เช่น ชื่อคนหรือแบรนด์"><button onclick="prRemember()">จำคำนี้</button><p id="prWords"></p></details>
<p class="hint">ก่อนบันทึก: Save และปิด CapCut · ตรวจคำจากข้อความเท่านั้น ไม่ฟังเสียงหรืออ่านข้อความติดภาพ</p>
</div></div>
<script>
let prData=null,prIssues=[],prJob=null,prEdits=new Map(),prPolling=false;
async function prPost(action,body={}){const c=new AbortController(),t=setTimeout(()=>c.abort(),15000);try{const r=await fetch('/api/proofread/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:c.signal});if(!r.ok)throw Error('เชื่อมต่อไม่สำเร็จ HTTP '+r.status);const j=await r.json();if(!j.ok)throw Error(j.error||'ทำงานไม่สำเร็จ');return j}finally{clearTimeout(t)}}
function prBusy(on){for(const id of ['prLoad','prScan','prMode'])document.getElementById(id).disabled=on;document.getElementById('prSave').disabled=on||!prEdits.size;document.getElementById('prCancel').disabled=!on||!prJob;document.querySelectorAll('#prResults input,#prResults textarea,#prResults button').forEach(x=>x.disabled=on)}
async function prLoad(){try{prData=await prPost('source');prIssues=[];prEdits.clear();prRender();document.getElementById('prWords').textContent=prData.words.join(' · ');document.getElementById('prStatus').textContent='โหลดข้อความล่าสุด '+prData.count+' ชิ้นแล้ว';return prData}catch(e){document.getElementById('prStatus').textContent=e.message;throw e}}
function prModeChanged(){prIssues=[];prEdits.clear();document.getElementById('prFilter').value='all';prRender();document.getElementById('prStatus').textContent='เปลี่ยนวิธีตรวจแล้ว กดตรวจคำด้วย UTCC เพื่อรับผลใหม่'}
async function prScan(){try{await prLoad();const j=await prPost('scan',{mode:document.getElementById('prMode').value,source_hash:prData.source_hash,source_project:prData.source_project});prJob=j.job_id;sessionStorage.setItem('proofreadJob',JSON.stringify({id:prJob,action:'scan'}));await prWatch('scan')}catch(e){document.getElementById('prStatus').textContent=e.message;prBusy(false)}}
async function prWatch(action){if(prPolling)return;prPolling=true;prBusy(true);try{while(prJob){const j=await evPost('status',{job_id:prJob});document.getElementById('prStatus').textContent=j.backend+' · '+j.message+' · '+j.completed+'/'+j.total+' ชุด · '+Math.max(0,Math.floor(Date.now()/1000-j.created))+' วินาที';document.getElementById('prCancel').disabled=action==='apply'||!!j.commit_started;if(j.state==='done'){prJob=null;sessionStorage.removeItem('proofreadJob');if(action==='scan'){prData=j.result;document.getElementById('prMode').value=j.result.mode||'full';prIssues=j.result.issues;prEdits.clear();prRender();document.getElementById('prStatus').textContent='ตรวจ '+j.result.checked+' ชิ้น · พบ '+prIssues.length+' จุด · ใช้ผลเดิม '+j.result.cached+' ชิ้น';}else{await prLoad();document.getElementById('prStatus').textContent=j.result.message+' · แก้ '+j.result.changed+' ชิ้น'}break}if(['failed','cancelled'].includes(j.state)){prJob=null;sessionStorage.removeItem('proofreadJob');throw Error(j.error||j.message)}await new Promise(r=>setTimeout(r,2000))}}catch(e){document.getElementById('prStatus').textContent=e.message+(prJob?' — โหลดหน้าใหม่เพื่อติดตามงาน':'')}finally{prPolling=false;prBusy(false)}}
function prRender(){const box=document.getElementById('prResults');box.replaceChildren();const filter=document.getElementById('prFilter').value;for(const issue of prIssues){if(filter!=='all'&&filter!==issue.issue_kind)continue;const card=document.createElement('div');card.style.cssText='padding:16px;margin:12px 0;border:1.5px solid var(--line);border-radius:14px;background:var(--inp)';const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.style.cssText='width:22px;height:22px;vertical-align:middle;margin-right:10px';check.checked=prEdits.has(issue.index);label.append(check,document.createTextNode(issue.kind+' · '+evClock(issue.start)+' · '+({spelling:'คำเสนอแก้',uncertain:'ไม่แน่ใจ — ตรวจชื่อ/ฟังเสียง',format:'เว้นวรรค / รูปแบบ'}[issue.issue_kind])));card.append(label);const before=document.createElement('p');before.textContent='เดิม: '+issue.original;card.append(before);const reason=document.createElement('p');reason.textContent='เหตุผล: '+issue.reason;card.append(reason);const edit=document.createElement('textarea');edit.setAttribute('aria-label','ข้อความที่เสนอแก้ ณ '+evClock(issue.start));edit.value=prEdits.get(issue.index)?.suggested||issue.suggested;edit.rows=2;edit.style.cssText='width:100%;padding:10px;background:var(--card);color:var(--txt);border:1px solid var(--line);border-radius:8px';const update=()=>{if(check.checked)prEdits.set(issue.index,{index:issue.index,original:issue.original,suggested:edit.value});else prEdits.delete(issue.index);prBusy(false)};check.onchange=update;edit.oninput=update;card.append(edit);const keep=document.createElement('button');keep.textContent='คงเดิม';keep.onclick=()=>{check.checked=false;edit.value=issue.original;update()};const remember=document.createElement('button');remember.textContent='จำศัพท์: '+issue.word;remember.onclick=()=>prRemember(issue.word);card.append(keep,remember);box.append(card)}document.getElementById('prSave').disabled=!prEdits.size;}
async function prSave(){if(!prData||!prEdits.size)return;try{const j=await prPost('apply',{source_hash:prData.source_hash,source_project:prData.source_project,edits:[...prEdits.values()]});prJob=j.job_id;sessionStorage.setItem('proofreadJob',JSON.stringify({id:prJob,action:'apply'}));await prWatch('apply')}catch(e){document.getElementById('prStatus').textContent=e.message;prBusy(false)}}
async function prRemember(word){try{const value=typeof word==='string'?word:document.getElementById('prWord').value;const j=await prPost('remember',{word:value});document.getElementById('prWords').textContent=j.words.join(' · ');prIssues=prIssues.filter(i=>i.issue_kind==='format'||i.word.toLowerCase()!==value.trim().toLowerCase());for(const [i,e] of prEdits)if(!prIssues.some(x=>x.index===i))prEdits.delete(i);prRender();document.getElementById('prStatus').textContent='จำศัพท์แล้ว: '+value}catch(e){document.getElementById('prStatus').textContent=e.message}}
async function prCancel(){if(prJob)await evPost('cancel',{job_id:prJob})}
window.addEventListener('DOMContentLoaded',()=>{try{const j=JSON.parse(sessionStorage.getItem('proofreadJob')||'null');if(j){prJob=j.id;prWatch(j.action)}}catch(e){sessionStorage.removeItem('proofreadJob')}});
</script>
'''
